func maxRatings(units [][]int) int64 {
	n := len(units[0])
	if n == 1 {
		var ans int64
		for _, x := range units {
			ans += int64(x[0])
		}
		return ans
	}

	var ans int64
	mn, mn2 := int(^uint(0)>>1), int(^uint(0)>>1)

	for _, x := range units {
		sort.Ints(x)
		ans += int64(x[1])
		if x[1] < mn2 {
			mn2 = x[1]
		}
		if x[0] < mn {
			mn = x[0]
		}
	}

	return ans - int64(mn2-mn)
}

function maxRatings(units: number[][]): number {
    const n = units[0].length;

    if (n === 1) {
        let ans = 0;
        for (const x of units) {
            ans += x[0];
        }
        return ans;
    }

    let ans = 0;
    let mn = Infinity;
    let mn2 = Infinity;

    for (const x of units) {
        x.sort((a, b) => a - b);
        ans += x[1];
        mn2 = Math.min(mn2, x[1]);
        mn = Math.min(mn, x[0]);
    }

    return ans - (mn2 - mn);
}
